body.query:
query GbifNetworkPage {
  resource(alias: "/the-gbif-network/global") {
    __typename
    ... on Article {
      id
      title
      summary
      excerpt
      body
      secondaryLinks {
        label
        url
      }
      documents {
        ...DocumentPreview
      }
      topics
      purposes
      audiences
      citation
      createdAt
    }
  }
}

fragment DocumentPreview on DocumentAsset {
  title
  file {
    url
    fileName
    contentType
    volatile_documentType
    details {
      size
    }
  }
}
